window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b293ad6573109050"]={"versions": [{"id": "FIG-b293ad6573109050", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitätsdiagramm der AUTOSAR-Methodik (SPEM-basiert) zur Spezifikation der Aktivität „Configure MCAL“ (Microcontroller Abstraction Layer Configuration) im Rahmen des ECU-Integrations- und Konfigurationsprozesses der Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität / Task:</strong></li>\n<li><code>Configure MCAL</code> (zentrale Task)</li>\n<li><strong>Rollen / Akteure:</strong></li>\n<li><code>ECU Integrator</code> (Kardinalität <code>1</code>, Assoziation <code>«performs»</code>)</li>\n<li><strong>Eingangs- und Ausgangsartefakte / Work Products:</strong></li>\n<li><code>BSW Module Delivered Bundle</code> (Kardinalität <code>0..1</code>, Assoziation <code>«input»</code>)</li>\n<li><code>AUTOSAR Standardized ECU Configuration Description</code> (im Diagrammtext als <code>AUTOSAR Standardized ECU...</code> abgeschnitten dargestellt; Kardinalität <code>0..1</code>, Assoziation <code>«input»</code>)</li>\n<li><code>ECU Configuration Description</code> (im Diagrammtext als <code>ECU Configuratio...</code> abgeschnitten dargestellt; Kardinalität <code>1</code>, bidirektionale Assoziation <code>«inoutput»</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>ECU Integrator</code> führt die Aktivität <code>Configure MCAL</code> durch.</li>\n<li>Als optionale Eingangsdaten dienen das <code>BSW Module Delivered Bundle</code> (Lieferpaket für BSW/MCAL-Module) sowie die standardisierte ECU-Konfigurationsbeschreibung (<code>AUTOSAR Standardized ECU Configuration Description</code>).</li>\n<li>Die Aktivität aktualisiert bzw. erweitert die bestehende ECU-Konfigurationsbeschreibung (<code>ECU Configuration Description</code>) inkrementell im Lese- und Schreibzugriff (<code>«inoutput»</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität beschreibt den methodischen Teilschritt zur gerätespezifischen Konfiguration hardwarenaher Treiber (MCAL) im AUTOSAR-Basissoftware-Stack. Werkzeugketten für die ECU-Konfiguration müssen das Einlesen der Modulbeschreibungen bzw. Standardparameter unterstützen und die Konfigurationswerte direkt in die Gesamtkonfiguration der ECU (<code>ECU Configuration Description</code>) einbetten. Die Kardinalität <code>1</code> mit <code>«inoutput»</code> verdeutlicht, dass eine bereits vorhandene ECU-Konfiguration modifiziert wird.</p>"}, {"id": "FIG-666e51548fd49441", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitätsdiagramm der AUTOSAR-Methodik (SPEM-basiert) zur Spezifikation der Aktivität „Configure MCAL“ (Microcontroller Abstraction Layer Configuration) im Rahmen des ECU-Integrations- und Konfigurationsprozesses der Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität / Task:</strong></li>\n<li><code>Configure MCAL</code> (zentrale Task)</li>\n<li><strong>Rollen / Akteure:</strong></li>\n<li><code>ECU Integrator</code> (Kardinalität <code>1</code>, Assoziation <code>«performs»</code>)</li>\n<li><strong>Eingangs- und Ausgangsartefakte / Work Products:</strong></li>\n<li><code>BSW Module Delivered Bundle</code> (Kardinalität <code>0..1</code>, Assoziation <code>«input»</code>)</li>\n<li><code>AUTOSAR Standardized ECU Configuration Description</code> (im Diagrammtext als <code>AUTOSAR Standardized ECU...</code> abgeschnitten dargestellt; Kardinalität <code>0..1</code>, Assoziation <code>«input»</code>)</li>\n<li><code>ECU Configuration Description</code> (im Diagrammtext als <code>ECU Configuratio...</code> abgeschnitten dargestellt; Kardinalität <code>1</code>, bidirektionale Assoziation <code>«inoutput»</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>ECU Integrator</code> führt die Aktivität <code>Configure MCAL</code> durch.</li>\n<li>Als optionale Eingangsdaten dienen das <code>BSW Module Delivered Bundle</code> (Lieferpaket für BSW/MCAL-Module) sowie die standardisierte ECU-Konfigurationsbeschreibung (<code>AUTOSAR Standardized ECU Configuration Description</code>).</li>\n<li>Die Aktivität aktualisiert bzw. erweitert die bestehende ECU-Konfigurationsbeschreibung (<code>ECU Configuration Description</code>) inkrementell im Lese- und Schreibzugriff (<code>«inoutput»</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität beschreibt den methodischen Teilschritt zur gerätespezifischen Konfiguration hardwarenaher Treiber (MCAL) im AUTOSAR-Basissoftware-Stack. Werkzeugketten für die ECU-Konfiguration müssen das Einlesen der Modulbeschreibungen bzw. Standardparameter unterstützen und die Konfigurationswerte direkt in die Gesamtkonfiguration der ECU (<code>ECU Configuration Description</code>) einbetten. Die Kardinalität <code>1</code> mit <code>«inoutput»</code> verdeutlicht, dass eine bereits vorhandene ECU-Konfiguration modifiziert wird.</p>"}], "trans": [{"from": "FIG-b293ad6573109050", "to": "FIG-666e51548fd49441", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
